#define KELLY_DECOMP_FULL_FEMENU_ENTRY
#define KELLY_DECOMP_FULL_FEMULTI_MENU
#define KELLY_DECOMP_BUILT_FEMENU_SELECT_PADDING
#include "KS/SRC/ks/FEMenu_shared.h"

#define MAX_CHEATS_PER_SCREEN 2
#define PHONE_TEXT_COLOR color32(49, 67, 48, 255)
#define PHONE_TEXT_COLOR_HI color32(73, 100, 72, 255)
#define PHONE_TOGGLE_TEXT_SIZE 0.555f

enum
{
    FEMENU_USE_SCALE = 0x080,
    FEMENU_NO_FLASHING = 0x100
};

class GraphicalMenuSystem;

class CheatCodeMenu : public FEMultiMenu
{
private:
    FEMenuEntry *cheats[MAX_CHEATS_PER_SCREEN];
    int menu_entry_cheat_index[MAX_CHEATS_PER_SCREEN];
    GraphicalMenuSystem* sys;
    int next_down, next_up;
    TextString *toggle_state[MAX_CHEATS_PER_SCREEN];
    PanelQuad *arrow_up;
    PanelQuad *arrow_down;

public:
    CheatCodeMenu(FEMenuSystem* s, FEManager* man, stringx p, stringx pf_name);
};

CheatCodeMenu::CheatCodeMenu(FEMenuSystem* s, FEManager* man, stringx p, stringx pf_name)
{
	cons(s, man, p, pf_name);
	sys = (GraphicalMenuSystem*) s;

	flags |= FEMENU_USE_SCALE;
	flags &= ~FEMENU_NO_FLASHING;
	scale = scale_high = PHONE_TOGGLE_TEXT_SIZE*1.5f;
	color = PHONE_TEXT_COLOR;
	color_high = PHONE_TEXT_COLOR_HI;
	color_high_alt = PHONE_TEXT_COLOR;

	next_up = next_down = -1;
}
